    [240+Math.cos(t*0.35+5)*65,200+Math.sin(t*0.55)*50,0.09,1.9],
    [400+Math.sin(t*0.45)*40,120+Math.cos(t*0.65+2)*55,0.11,2.1],
    [60+Math.cos(t*0.75+3)*45,120+Math.sin(t*0.85+1)*35,0.05,2.4]
  ];
  let aS=0,iS=0;
  for(let i=0;i<src.length;i++){
    const[sX,sY,f,sp]=src[i],d=Math.sqrt((sx-sX)**2+(sy-sY)**2),pf=f*p(i)*0.15;
    aS+=Math.sin(d*pf-t*sp);iS+=Math.sin(d*pf*0.7+t*sp*0.6+1.5);
  }
  const act=aS/8,inh=iS/8;
  const bg=(Math.sin(sx*0.02*p(0)+sy*0.0125*p(1)+t*0.8)+Math.sin(sx*0.015*p(2)-sy*0.02*p(3)+t*1.1))/2+Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2;
  const cx=240,cy=120,dist=Math.sqrt((sx-cx)**2+(sy-cy)**2),ang=Math.atan2(sy-cy,sx-cx);
