    const bx=18+i*58,bw=p(i)*7.5;
    if(dy<1.8&&sx>bx&&sx<bx+bw)ui+=0.55;
    const pulse=Math.sin(t*1.2+i*0.9)*0.5+0.5;
    if(dy<1.5&&sx>bx+bw+4&&sx<bx+bw+4+3)ui+=0.3*pulse;
  }
  for(let i=0;i<6;i++){const vx=75+i*90,dvx=Math.abs(sx-vx);if(dvx<0.7)ui+=0.35;}
  if(Math.abs(sy-234)<3.5){for(let i=0;i<10;i++){const px=25+i*46,dp=Math.sqrt((sx-px)**2+(sy-234)**2);if(dp<2.8)ui+=0.85;if(dp<7)ui+=0.25*(1-dp/7);}}
  const titleBar=Math.abs(sy-10);
  if(titleBar<6){const flicker=Math.sin(sx*0.8+t*3)*0.5+0.5;if(flicker>0.6)ui+=0.3*(1-titleBar/6);}
