  const pal=[[0,0,15],[0,30,70],[0,160,190],[0,255,170],[255,255,90],[255,130,45],[255,35,115],[190,0,255],[60,0,100],[0,0,15]];
  const idx=v*(pal.length-1),i=Math.min(idx|0,pal.length-2),f=idx-i;
  const lum=0.8+Math.sin(reaction*Math.PI)*0.2,edge=Math.abs(reaction)>0.6?1.35:1.0,uiG=ui>0.3?1.25:1.0,m=lum*edge*uiG;
  return[Math.min(255,(pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*m)|0,Math.min(255,(pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*m)|0,Math.min(255,(pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*m)|0];
}
